create extension if not exists vector;
create table tenants(id serial primary key,slug text unique not null,name text not null,domain text unique,active bool default true,created_at timestamptz default now());
create table users(id serial primary key,name text,email text unique,pass text,role text default 'agent',is_ai bool default false,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table teams(id serial primary key,name text,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table team_members(team_id int references teams on delete cascade,user_id int references users on delete cascade,primary key(team_id,user_id),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table channels(id serial primary key,name text,driver text not null,config jsonb default '{}',team_id int references teams,active bool default true,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade); -- waha|baileys|zernio
create table contacts(id serial primary key,name text,handle text,channel_id int references channels,data jsonb default '{}',unique(channel_id,handle),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table stages(id serial primary key,name text,pos int,kind text default 'open',tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade); -- open|won|lost
create table agents(id serial primary key,name text,channel_ids int[] default '{}',llm jsonb,stt jsonb,tts jsonb,prompt text default '',tone text default '',rules text default '',forbidden text default '',tools text[] default '{handoff,move_stage,book}',active bool default true,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table conversations(id serial primary key,contact_id int references contacts,channel_id int references channels,stage_id int references stages,assignee_id int references users,team_id int references teams,agent_id int references agents,ai_on bool default true,amount numeric,unread int default 0,last_at timestamptz default now(),last_in_at timestamptz,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table participants(conversation_id int references conversations on delete cascade,user_id int references users,primary key(conversation_id,user_id),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table messages(id bigserial primary key,conversation_id int references conversations on delete cascade,dir text,kind text default 'text',body text,media_url text,author_id int,ai bool default false,ext_id text,at timestamptz default now(),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade); -- kind: text|audio|image|note(privada)|comment|dm
create index on messages(conversation_id,at);
create table docs(id serial primary key,agent_id int references agents on delete cascade,title text,content text,emb vector(1536),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table appointments(id serial primary key,contact_id int references contacts,title text,starts_at timestamptz,ends_at timestamptz,gcal_id text,status text default 'agendado',tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table flows(id serial primary key,name text,trigger jsonb default '{}',steps jsonb default '[]',active bool default true,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table jobs(id serial primary key,run_at timestamptz,conversation_id int,flow_id int,step int default 0,done bool default false,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table payments(id serial primary key,contact_id int,provider text,ext_id text,amount numeric,status text default 'pendente',link text,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table catalog(id serial primary key,name text,sku text,price numeric,stock int default 0,data jsonb default '{}',tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table posts(id serial primary key,channel_id int,body text,media_url text,schedule_at timestamptz,status text default 'rascunho',tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table ads(id serial primary key,name text,data jsonb default '{}',status text default 'rascunho',tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
create table settings(key text,value jsonb,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,primary key(tenant_id,key));
create table orders(id serial primary key,source text,contact_id int,items jsonb default '[]',total numeric,status text default 'novo',ext_id text,created_at timestamptz default now(),tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade);
